-- Update existing blog: replace unavailable "Kućna pomoćnica" with "Dečko".
-- This script updates only the existing article body and related product IDs.
-- It leaves the title, slug, SEO fields, publication date and hero image unchanged.
-- Safe to run more than once.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;

SET @blog_slug := 'najcitanije-knjige-2026-20-naslova-koje-europa-trenutno-obozava';
SET @blog_description := CONVERT(FROM_BASE64(CONCAT(
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    '',
    ''
)) USING utf8mb4);

SET @related_products := (
    SELECT CONCAT(
        '[',
        COALESCE(
            GROUP_CONCAT(
                CAST(p.id AS CHAR)
                ORDER BY FIELD(p.slug,
                    'dan-brown-tajna-svih-tajni',
                    'freida-mcfadden-decko',
                    'freida-mcfadde-tajna-kucne-pomocnice',
                    'frieda-mcfadden-kucna-pomocnica-te-promatra',
                    'freida-mcfadden-profesorica',
                    'mel-robbins-teorija-pusti-ih',
                    'clear-james-atomske-navike-1741176897',
                    'andy-weir-projekt-spasitelj',
                    'emily-bronte-orkanski-visovi-2',
                    'maggie-ofarrell-hamnet',
                    'valerie-perrin-svjeza-voda-za-cvijece',
                    'matt-haig-midnight-library',
                    'alex-michaelides-nijema-pacijentica',
                    'albert-camus-stranac',
                    'antoine-de-saint-exupery-mali-princ-4',
                    'j-k-rowling-harry-potter-i-kamen-mudraca-3',
                    'sarah-j-maas-dvor-trnja-i-ruza',
                    'rebecca-yarros-cetvrto-krilo',
                    'rebecca-yarros-zeljezni-plamen',
                    'rebecca-yarros-oluja-oniksa'
                )
                SEPARATOR ','
            ),
            ''
        ),
        ']'
    )
    FROM products AS p
    WHERE p.slug IN (
        'dan-brown-tajna-svih-tajni',
        'freida-mcfadden-decko',
        'freida-mcfadde-tajna-kucne-pomocnice',
        'frieda-mcfadden-kucna-pomocnica-te-promatra',
        'freida-mcfadden-profesorica',
        'mel-robbins-teorija-pusti-ih',
        'clear-james-atomske-navike-1741176897',
        'andy-weir-projekt-spasitelj',
        'emily-bronte-orkanski-visovi-2',
        'maggie-ofarrell-hamnet',
        'valerie-perrin-svjeza-voda-za-cvijece',
        'matt-haig-midnight-library',
        'alex-michaelides-nijema-pacijentica',
        'albert-camus-stranac',
        'antoine-de-saint-exupery-mali-princ-4',
        'j-k-rowling-harry-potter-i-kamen-mudraca-3',
        'sarah-j-maas-dvor-trnja-i-ruza',
        'rebecca-yarros-cetvrto-krilo',
        'rebecca-yarros-zeljezni-plamen',
        'rebecca-yarros-oluja-oniksa'
    )
      AND p.status = 1
      AND p.quantity > 0
);

SET @active_products_found := (
    SELECT COUNT(*)
    FROM products AS p
    WHERE p.slug IN (
        'dan-brown-tajna-svih-tajni',
        'freida-mcfadden-decko',
        'freida-mcfadde-tajna-kucne-pomocnice',
        'frieda-mcfadden-kucna-pomocnica-te-promatra',
        'freida-mcfadden-profesorica',
        'mel-robbins-teorija-pusti-ih',
        'clear-james-atomske-navike-1741176897',
        'andy-weir-projekt-spasitelj',
        'emily-bronte-orkanski-visovi-2',
        'maggie-ofarrell-hamnet',
        'valerie-perrin-svjeza-voda-za-cvijece',
        'matt-haig-midnight-library',
        'alex-michaelides-nijema-pacijentica',
        'albert-camus-stranac',
        'antoine-de-saint-exupery-mali-princ-4',
        'j-k-rowling-harry-potter-i-kamen-mudraca-3',
        'sarah-j-maas-dvor-trnja-i-ruza',
        'rebecca-yarros-cetvrto-krilo',
        'rebecca-yarros-zeljezni-plamen',
        'rebecca-yarros-oluja-oniksa'
    )
      AND p.status = 1
      AND p.quantity > 0
);

SET @blog_id := (
    SELECT MIN(id)
    FROM pages
    WHERE `group` = 'blog'
      AND slug = @blog_slug
);

UPDATE pages
SET description = @blog_description,
    related_products = @related_products,
    updated_at = NOW()
WHERE id = @blog_id;

COMMIT;

SELECT
    @blog_id AS blog_id,
    @blog_slug AS slug,
    @active_products_found AS active_related_products,
    CASE
        WHEN @blog_id IS NULL THEN 'WARNING: blog not found; run the full import SQL first'
        WHEN @active_products_found <> 20 THEN 'WARNING: expected 20 active products with quantity > 0'
        ELSE 'OK'
    END AS update_check;
